class Solution {public:bool solve(string a,string b,string target){if(a.size()+b.size()!=target.size())return false;vector<bool>d(b.size()+1);d[0]=true;for(int j=1;j<=(int)b.size();j++)d[j]=d[j-1]&&b[j-1]==target[j-1];for(int i=1;i<=(int)a.size();i++){d[0]=d[0]&&a[i-1]==target[i-1];for(int j=1;j<=(int)b.size();j++)d[j]=(d[j]&&a[i-1]==target[i+j-1])||(d[j-1]&&b[j-1]==target[i+j-1]);}return d[b.size()];}};